export type notificationsReadResponse = (notificationsReadResponseSuccess | notificationsReadResponseError)

export const getNotificationsReadUrl = (notificationId: string,) => {




  return `/api/v1/notifications/${notificationId}/read/`
}

/**
 * @summary Read Notification
 */
export const notificationsRead = async (notificationId: string,
    notificationStatusSchemaNull?: NotificationStatusSchema | null, options?: Parameters<typeof compassFetch>[1]): Promise<notificationsReadResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
return compassFetch<notificationsReadResponse>(getNotificationsReadUrl(notificationId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(notificationStatusSchemaNull)
  }
);}
